import{_ as i,o as r,c as t,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS G/H (Day 1) - OSD: Scrub & Repair","description":"","frontmatter":{"title":"CDS G/H (Day 1) - OSD: Scrub & Repair","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-24T00:00:00.000Z","tags":["Ceph","分布式存储","scrub","repair","OSD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_OSD_-_Scrub_Repair.md","filePath":"posts/2014/CDS_G_H_Day_1_-_OSD_-_Scrub_Repair.md","lastUpdated":1780459816000}'),o={name:"posts/2014/CDS_G_H_Day_1_-_OSD_-_Scrub_Repair.md"};function a(e,l,p,_,n,u){return r(),t("div",null,[...l[0]||(l[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： 与会者</p><p><strong>会议主题</strong>： 讨论Ceph分布式存储系统中OSD的Scrub和Repair功能</p><p><strong>会议内容</strong>：</p><p><strong>一、主要议题</strong></p><ol><li><p><strong>Scrub和Repair问题</strong>：</p><ul><li>当前Scrub功能在处理不一致性时，需要手动分析中央日志，难以识别具体问题。</li><li>建议增加接口，让OSD在Scrub PG时跟踪不一致性，并记录到LevelDB中。</li><li>将不一致性信息与活跃区间逻辑绑定，便于后续处理。</li></ul></li><li><p><strong>接口设计</strong>：</p><ul><li>定义所有对象不一致的方式，作为基础数据结构。</li><li>使用该数据结构描述不一致对象，并记录到LevelDB中。</li><li>增加查询不一致PG和对象的接口。</li><li>增加修复不一致对象的接口，并考虑异步执行。</li></ul></li><li><p><strong>实现细节</strong>：</p><ul><li>使用SnapMapper等架构设备记录不一致信息。</li><li>使用新的Radius API，需要提供Epic序列号，以便比较请求。</li><li>增加读取特定副本的接口，以及修复副本的接口。</li></ul></li><li><p><strong>一致性信息结构</strong>：</p><ul><li>不一致性信息应包含与对象和一致性设计相关的所有信息。</li><li>避免在结构中遗漏信息，否则无法传播给Liberators。</li></ul></li><li><p><strong>Replica修复</strong>：</p><ul><li>使用列表指定用于修复的正确副本。</li><li>考虑将修复操作与Radius操作分离。</li></ul></li><li><p><strong>自动修复</strong>：</p><ul><li>在Scrub命令中使用接口实现自动修复，或设置自动修复策略。</li></ul></li><li><p><strong>内部OSD元数据不一致</strong>：</p><ul><li>通过修改对象信息来解决内部OSD元数据不一致。</li><li>考虑将修复操作与Radius操作分离。</li></ul></li></ol><p><strong>二、决定事项</strong></p><ol><li>增加接口，让OSD在Scrub PG时跟踪不一致性，并记录到LevelDB中。</li><li>定义不一致信息的数据结构，并记录到LevelDB中。</li><li>增加查询不一致PG和对象的接口。</li><li>增加修复不一致对象的接口，并考虑异步执行。</li><li>考虑将修复操作与Radius操作分离。</li><li>实现自动修复功能。</li><li>考虑将内部OSD元数据不一致的修复操作与Radius操作分离。</li></ol><p><strong>三、后续行动计划</strong></p><ol><li>与会者将根据会议讨论结果进行代码实现。</li><li>定期进行代码审查和讨论。</li><li>完成功能开发后，进行测试和验证。</li></ol><p><strong>四、其他事项</strong></p><ol><li>会议中讨论了使用Radius API或PGTell接口的问题，最终决定使用Radius API。</li><li>会议决定将修复操作与Radius操作分离，以避免引入过多的复杂性。</li></ol>',14)])])}const c=i(o,[["render",a]]);export{g as __pageData,c as default};
